using System;
using System.Collections;
using System.Collections.Generic;
using FMODUnity;
using LittleLeo;
using UnityEngine;

namespace Astrea;

public class UnitFeedbackHandler : MonoBehaviour
{
	[Header("Components")]
	[SerializeField]
	private GameObject effectFeedbackPrefab;

	[SerializeField]
	private UnitEffects unitEffects;

	[Header("SFX")]
	[SerializeField]
	private EventReference effectsSFX;

	private Coroutine spawnFeedbackCoroutine;

	private bool spawnFeedbackCoroutineRunning;

	private float timeBetweenFeedbacks = 0.6f;

	private List<Action> feedbacksActionList = new List<Action>();

	public Coroutine SpawnFeedbackCoroutine => spawnFeedbackCoroutine;

	public void EnqueueEffectFeedbackAndPlay(Effect effect, int amount = 0, bool gainingEffectVFXAndSFX = false, bool playInstantSFX = false)
	{
		if (playInstantSFX)
		{
			PlayGainEffectSFX(effect, amount, gainingEffectVFXAndSFX);
		}
		feedbacksActionList.Add(delegate
		{
			SpawnEffectFeedback(effect, amount, gainingEffectVFXAndSFX, playInstantSFX);
		});
		StartFeedbacksCoroutine();
	}

	public void AddFeedbackAndEnqueueEffectFeedback(Effect effect, int amount, bool gainingEffectVFXAndSFX = true)
	{
		feedbacksActionList.Add(delegate
		{
			SpawnEffectFeedback(effect, amount, gainingEffectVFXAndSFX, playInstantSFX: false);
			GetComponent<SpriteControl>().PlayVisualEffect(VisualEffectType.Blink);
			unitEffects.AddEffect(effect, amount, effectFeedback: false);
		});
	}

	public void PlayFeedbackNotEnqueuing(Effect effect)
	{
		SpawnEffectFeedback(effect, 0, gainingEffectVFXAndSFX: false, playInstantSFX: false);
	}

	private void SpawnEffectFeedback(Effect effect, int amount, bool gainingEffectVFXAndSFX, bool playInstantSFX)
	{
		if (!playInstantSFX)
		{
			PlayGainEffectSFX(effect, amount, gainingEffectVFXAndSFX);
		}
		ReferenceSingleton<PoolHandler>.Instance.GetObject(effectFeedbackPrefab.name).GetComponent<OmenEffectFeedback>().PlayEffectFeedback(effect, amount, base.transform.position);
	}

	private void PlayGainEffectSFX(Effect effect, int amount, bool gainingEffectVFXAndSFX)
	{
		if (gainingEffectVFXAndSFX && !effect.DisableGainEffectSFX)
		{
			if (effect.EnableGainEffectSFX && effect.IsVFXEnabled())
			{
				effect.PlayGainEffectSFX();
			}
			else
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(effectsSFX);
			}
		}
	}

	public void EnqueueRemoveEffectFeedbackAndPlay(Effect effect, int amount)
	{
		feedbacksActionList.Add(delegate
		{
			SpawnRemoveEffectFeedback(effect, amount);
		});
		StartFeedbacksCoroutine();
	}

	private void SpawnRemoveEffectFeedback(Effect effect, int amount)
	{
		ReferenceSingleton<PoolHandler>.Instance.GetObject(effectFeedbackPrefab.name).GetComponent<OmenEffectFeedback>().PlayRemoveEffectFeedback(effect, base.transform.position);
	}

	public void EnqueueIncreaseDecreaseEffectFeedbackAndPlay(Effect effect, int amount, bool gainingEffectVFXAndSFX)
	{
		if (amount > 0)
		{
			PlayGainEffectSFX(effect, amount, gainingEffectVFXAndSFX);
		}
		feedbacksActionList.Add(delegate
		{
			SpawnIncreaseDecreaseEffectFeedback(effect, amount, gainingEffectVFXAndSFX);
		});
		StartFeedbacksCoroutine();
	}

	private void SpawnIncreaseDecreaseEffectFeedback(Effect effect, int amount, bool gainingEffectVFXAndSFX)
	{
		ReferenceSingleton<PoolHandler>.Instance.GetObject(effectFeedbackPrefab.name).GetComponent<OmenEffectFeedback>().PlayIncreaseDecreaseEffectFeedback(effect, base.transform.position, amount);
	}

	public void EnqueueOmenFeedbackAndPlay(Action feedbackAction)
	{
		feedbacksActionList.Add(feedbackAction);
		StartFeedbacksCoroutine();
	}

	public float GetTotalTimeEffectFeedbacksAnimation()
	{
		if (feedbacksActionList.Count == 0)
		{
			return 0f;
		}
		return timeBetweenFeedbacks * (float)feedbacksActionList.Count + 0.1f;
	}

	public IEnumerator FeedbacksCoroutine()
	{
		spawnFeedbackCoroutineRunning = true;
		yield return InvokeAlternatives.WaitForFrames(6);
		for (int i = 0; i < feedbacksActionList.Count; i++)
		{
			feedbacksActionList[i]();
			yield return new WaitForSeconds(timeBetweenFeedbacks);
		}
		feedbacksActionList.Clear();
		spawnFeedbackCoroutine = null;
		spawnFeedbackCoroutineRunning = false;
	}

	private void StartFeedbacksCoroutine()
	{
		if (spawnFeedbackCoroutine == null && !spawnFeedbackCoroutineRunning)
		{
			spawnFeedbackCoroutine = ReferenceSingleton<CoroutineHandler>.Instance.Run(FeedbacksCoroutine());
		}
	}

	public void StartFeedbacksCoroutineIfAnyFeedbackOnQueue()
	{
		if (spawnFeedbackCoroutine == null && !spawnFeedbackCoroutineRunning && feedbacksActionList.Count > 0)
		{
			Debug.Log("!!!!!!!!!! INITIALIZE BATTLE STATE FAILED TO RUN ENEMY STARTING EFFECTS COROUTINE !!!!!!!!!!");
			spawnFeedbackCoroutine = ReferenceSingleton<CoroutineHandler>.Instance.Run(FeedbacksCoroutine());
		}
	}

	public void EnqueueStartFeedbacksCoroutineActionsQueueState()
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(FeedbacksCoroutine());
	}

	public void ClearFeedbacksActionList()
	{
		feedbacksActionList.Clear();
	}
}
